          renewalTermConfiguration:
            enableAutoRenew: {{ enableAutoRenew }}
          variablePaymentTermConfiguration:
            paymentRequestApprovalStrategy: "{{ paymentRequestApprovalStrategy }}"
            expirationDuration: "{{ expirationDuration }}"
